mapper.delete:
DELETE FROM t_mp_month_sale_plan
 WHERE FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
   AND YEAR = #{year,jdbcType=DECIMAL}
   AND MONTH = #{month,jdbcType=DECIMAL}

mapper.update:
UPDATE t_mp_month_sale_plan msp
  LEFT JOIN t_mdm_customer_info mci
    ON msp.FACTORY_CODE = mci.FACTORY_CODE
   AND msp.CUSTOM_CODE = mci.CUSTOM_CODE
   AND IFNULL(mci.IS_DELETE, 0) = 0
   SET msp.IS_IMPORTANT_CUSTOM = IFNULL(mci.IS_IMPORTANT_CUSTOM, 0)
 WHERE msp.FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
   AND msp.YEAR = #{year,jdbcType=DECIMAL}
   AND msp.MONTH = #{month,jdbcType=DECIMAL}

UPDATE t_mp_month_sale_plan msp
   SET msp.IS_ENSURE_PLAN = (SELECT COUNT(1) FROM t_mdm_must_finish_plan mfp
                              WHERE msp.FACTORY_CODE = mfp.FACTORY_CODE
                                AND msp.YEAR = mfp.YEAR
                                AND msp.MONTH = mfp.MONTH
                                AND msp.CUSTOM_CODE = mfp.CUSTOM_CODE
                                AND msp.PRODUCT_CODE = mfp.PRODUCT_CODE
                                AND msp.LOCATION_TYPE = mfp.LOCATION_TYPE
                            )
WHERE msp.FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
  AND msp.YEAR = #{year,jdbcType=DECIMAL}
  AND msp.MONTH = #{month,jdbcType=DECIMAL}
